1	#ifndef SG_FUSED_SM90_FUSED_MEGAKERNEL_CUH_
2	#define SG_FUSED_SM90_FUSED_MEGAKERNEL_CUH_
3	// ============================================================================
4	// csrc/fused/sm_90/fused_megakernel.cuh — REAL component-composition L3/L1
5	// persistent megakernel substrate (Phase 3 Stage 5).
6	//
7	// This is the composition seam. It pulls the REAL optimizer device-function
8	// component (opt_components.cuh → csrc/algorithms/<opt>.h) and the REAL model
9	// stage device functions (model_stages.cuh) and composes the solver-chosen
10	// (model, optimizer) into ONE persistent __global__ over the shared substrate
11	// (task queue, %smid SM-pin, hand-built GridBarrier, warp-spec hand-off).
12	//
13	// It REPLACES megakernel_demo.cu's toy `opt_update<Opt>` (4 optimizers + an
14	// AdamW fallback for the other 7). Every cell that includes this file gets the
15	// real, distinct per-optimizer math via apply_optimizer<OptId> — no fallback,
16	// no template-of-one-optimizer-from-another, no toy substitute.
17	//
18	// TIERING (matches grokking_optimizers/megakernel.py solver):
19	//   FuseTier::L3 — fuse forward + backward + optimizer in one launch.
20	//   FuseTier::L1 — fuse ONLY the optimizer tail (model fwd/bwd are the
21	//                  framework's own / the per-op CUTLASS launches). 46 of the 99
22	//                  cells are L1 on the GPU arches (register-pressure bound).
23	// ============================================================================
24	
25	#include "csrc/fused/megakernel_common.cuh"
26	#include "csrc/backends/cuda/sm_90/warp_specialize.cuh"
27	#include "csrc/fused/sm_90/opt_components.cuh"
28	#include "csrc/fused/sm_90/model_stages.cuh"
29	
30	#include <cuda_runtime.h>
31	#include <cstdint>
32	#include <cassert>
33	
34	namespace sg { namespace fused { namespace sm90 {
35	
36	namespace wgs = ::sg::sm90::wgs;
37	
38	enum class FuseTier : int { L1 = 1, L3 = 3 };
39	
40	// Per-warp-group register targets for the producer/consumer split (§3.4).
41	// On Hopper setmaxnreg is warp-group granular (128 threads / 4 warps). The
42	// fused kernel launches 256 threads = TWO warp-groups so the split is well
43	// formed: warp-group 0 is the PRODUCER (staging / queue / row-context loads,
44	// few registers) and warp-group 1 is the CONSUMER (the heavy WGMMA-class
45	// compute + optimizer tail). Partitioning lets the consumer claim a large
46	// register file WITHOUT the producer's allocation counting against the L3
47	// footprint, so no single warp-group needs the full fused register budget.
48	// SG_TUNED_PROD_REGS / SG_TUNED_CONS_REGS — the setmaxnreg targets for the
49	// producer / consumer warp-groups, exposed as autotuner dims. The SAME macro
50	// tokens drive the warp-specialized tile pipeline (csrc/backends/cuda/sm_90/
51	// tile_pipeline.cuh); a single -DSG_TUNED_{PROD,CONS}_REGS=N flag therefore
52	// tunes whichever sm_90 register-split path the unit being built compiles.
53	// Defaults equal the prior literals (32 / 200) so an untuned / no-JSON build is
54	// byte-identical (verified via nvcc -E). NOTE: tile_pipeline.cuh's #ifndef
55	// defaults differ (40 / 232); that is harmless ONLY because the two headers are
56	// never co-included in one TU (fused_megakernel reaches setmaxnreg via
57	// warp_specialize.cuh, not via wgmma.cuh→tile_pipeline.cuh — the latter is
58	// pulled solely by decoder_tc_selftest.cu). If a future TU includes both, the
59	// divergent #ifndef defaults make include order decide the value — then they
60	// must be reconciled to one default (see report).
61	#ifndef SG_TUNED_PROD_REGS
62	#define SG_TUNED_PROD_REGS 32
63	#endif
64	#ifndef SG_TUNED_CONS_REGS
65	#define SG_TUNED_CONS_REGS 200
66	#endif
67	static constexpr int kProducerRegsF = SG_TUNED_PROD_REGS;
68	static constexpr int kConsumerRegsF = SG_TUNED_CONS_REGS;
69	// Warp-group size on Hopper (threads). 256-thread block => 2 warp-groups.
70	static constexpr int kWarpGroupThreads = 128;
71	// SG_TUNED_MEGA_BLOCK (the per-CTA thread count) is defined in
72	// megakernel_common.cuh (#include'd above) so the fused megakernel and the
73	// model drivers share one tunable; default 256 → byte-identical untuned build.
74	// NEEDS-PARITY before a non-default winner ships (2-warp-group split + shared
75	// buffer sizing assumptions; see the macro's definition site).
76	static constexpr int kFusedBlockThreads = SG_TUNED_MEGA_BLOCK;
77	
78	// =========================================================================
79	//  Optimizer stage — the fused tail. Pulls tensors from the queue and applies
80	//  the REAL apply_optimizer<Opt> elementwise over this SM's resident state
81	//  slice (kept L2-warm via the %smid pin, §1.3).
82	// =========================================================================
83	// #6 — per-Opt pointer rebase via `if constexpr`. Rather than unconditionally
84	// bumping all 8 optimizer-state pointers per task (8 predicated adds + the
85	// chance the allocator keeps every field live), only the pointers the CHOSEN
86	// optimizer actually dereferences are rebased to the tensor slice; the rest are
87	// compiled out. `ts` starts as a copy of the const& `st` (the scalar
88	// hyperparams must be present), but the dead-pointer rebases vanish, lowering
89	// the local/register footprint of the tail.
90	template <OptId Opt>
91	__device__ __forceinline__ FusedOptState rebase_state(const FusedOptState& st,
92	                                                       int64_t off) {
93	    FusedOptState ts = st;
94	    if constexpr (Opt == OptId::AdamW || Opt == OptId::Lion ||
95	                  Opt == OptId::Grokfast || Opt == OptId::GrokAdamW ||
96	                  Opt == OptId::LookSAM || Opt == OptId::Prodigy ||
97	                  Opt == OptId::NeuralGrok || Opt == OptId::SuperGrok11 ||
98	                  Opt == OptId::SuperGrok15 || Opt == OptId::SuperGrok2) {
99	        if (ts.exp_avg)    ts.exp_avg    += off;   // m (all Adam-family tails)
100	    }
101	    if constexpr (Opt != OptId::Lion && Opt != OptId::Muon) {
102	        if (ts.exp_avg_sq) ts.exp_avg_sq += off;   // v (everyone but Lion/Muon)
103	    }
104	    if constexpr (Opt == OptId::Grokfast || Opt == OptId::GrokAdamW) {
105	        if (ts.ema)        ts.ema        += off;
106	    }
107	    if constexpr (Opt == OptId::Prodigy) {
108	        if (ts.s_track)    ts.s_track    += off;
109	    }
110	    if constexpr (Opt == OptId::SuperGrok11 || Opt == OptId::SuperGrok15) {
111	        if (ts.mu)         ts.mu         += off;
112	    }
113	    if constexpr (Opt == OptId::LookSAM) {
114	        if (ts.sam_dir)    ts.sam_dir    += off;
115	    }
116	    if constexpr (Opt == OptId::Muon) {
117	        if (ts.orth)       ts.orth       += off;
118	    }
119	    if constexpr (Opt == OptId::SuperGrok2) {
120	        if (ts.smart_grad) ts.smart_grad += off;
121	    }
122	    return ts;
123	}
124	
125	template <OptId Opt>
126	__device__ void fused_optimizer_stage(const PersistentContext& ctx,
127	                                       float* __restrict__ params,
128	                                       const float* __restrict__ grad,
129	                                       const int* sizes, const int* offsets,
130	                                       int step, const FusedOptState& st) {
131	    __shared__ int task_slot;
132	    TaskQueue q = ctx.queue();
133	    for (int t = q.next_block(&task_slot); t < ctx.n_tasks;
134	         t = q.next_block(&task_slot)) {
135	        const int n = sizes[t];
136	        // #2 int64: off is the tensor's element offset into the global param
137	        // blob and can exceed 2^31; rebase the slice pointers in 64-bit so the
138	        // base address is correct past 2 Gi elements. The within-tensor index
139	        // (base/i below) is bounded by n (an int) but apply_optimizer takes an
140	        // int64_t idx so the addition never truncates. Behavior-preserving.
141	        const int64_t off = (int64_t)offsets[t];
142	        // #6: rebase only the pointers Opt uses to this tensor's slice.
143	        const FusedOptState ts = rebase_state<Opt>(st, off);
144	        float* __restrict__ p = params + off;
145	        const float* __restrict__ g = grad + off;
146	        // #1 — float4 vectorization of the per-element tail. Each thread strides
147	        // over groups of 4 CONSECUTIVE indices and calls the canonical per-
148	        // element optimizer fn 4× on [4j .. 4j+3]; because the four indices are
149	        // contiguous and the buffers are __restrict__, the loads/stores of
150	        // params/grad/m/v coalesce into 128-bit float4 transactions. The
151	        // canonical algorithm math (csrc/algorithms/<opt>.h via apply_optimizer)
152	        // is CALLED, never re-inlined — only the loop's access pattern changes.
153	        const int n4 = n >> 2;                  // # of full float4 groups
154	        for (int j = threadIdx.x; j < n4; j += blockDim.x) {
155	            const int64_t base = (int64_t)j << 2;   // #2 int64 within-tensor idx
156	            apply_optimizer<Opt>(p, g, base + 0, step, ts);
157	            apply_optimizer<Opt>(p, g, base + 1, step, ts);
158	            apply_optimizer<Opt>(p, g, base + 2, step, ts);
159	            apply_optimizer<Opt>(p, g, base + 3, step, ts);
160	        }
161	        // Scalar tail for the remainder (n not a multiple of 4).
162	        for (int i = (n4 << 2) + (int)threadIdx.x; i < n; i += blockDim.x) {
163	            apply_optimizer<Opt>(p, g, (int64_t)i, step, ts);
164	        }
165	    }
166	}
167	
168	// =========================================================================
169	//  Stage 5 — TRUE cross-phase fusion (bwd→opt), SMEM-resident grad tile.
170	//
171	//  HONEST SCOPE / what is realized vs deferred:
172	//   * REALIZED: the backward grad of a tensor and the optimizer update of the
173	//     SAME tensor are fused into ONE queue-pulled body. The grad is computed
174	//     into a per-CTA __shared__ tile and the optimizer reads it from SMEM — the
175	//     grad NEVER round-trips through the global `grad` buffer, and the grid
176	//     barrier that used to separate bwd from opt is ELIMINATED (3 phases / 2
177	//     barriers → 2 phases / 1 barrier per L3 step). This is correct because
178	//     both the activation backward (grad = acts*act'(param)) and every
179	//     apply_optimizer<Opt> are strictly ELEMENT-LOCAL for a given tensor: no
180	//     cross-element and no cross-tensor dependency couples bwd to opt, so no
181	//     grid-wide sync is needed between them for the same tensor, and the SAME
182	//     CTA owns the tensor end-to-end within one queue pull (no work-stealing
183	//     hand-off can split a tensor's bwd from its opt).
184	//   * STILL GLOBAL (deferred, with reason): the forward `acts` buffer. fwd and
185	//     bwd are split by a grid barrier AND the task queue is reset between them,
186	//     so under work-stealing (§1.2) a different CTA may own a tensor in bwd than
187	//     owned it in fwd. A CTA-local SMEM acts tile therefore CANNOT be carried
188	//     across the fwd→bwd barrier safely. Making acts SMEM-resident would require
189	//     a stable tensor→CTA partition (abandoning work-stealing) or DSMEM cluster
190	//     sharing — out of scope for a no-silicon, behavior-preserving change. So
191	//     acts stays global; that round-trip is documented, not hidden.
192	//   * The apply math is still CALLED via apply_optimizer<Opt> (drift-guard safe);
193	//     only the grad SOURCE pointer changes from global to the SMEM tile, and the
194	//     params/state pointers are rebased per chunk so the canonical algorithm
195	//     addresses the correct global state. 🟡 perf (no silicon to measure).
196	//
197	//  The grad value itself is BIT-IDENTICAL to the previous two-phase path:
198	//  grad = acts[gi] * model_activation_grad<M>(params[gi]) — same expression,
199	//  same operand order; only its storage class (SMEM vs global) changed.
200	// =========================================================================
201	// SG_TUNED_GRAD_TILE — floats per SMEM grad tile (the cross-phase bwd→opt
202	// fusion buffer). Default 1024 (4 KB → byte-identical untuned build). NEEDS-
203	// PARITY before shipping a non-default winner: it sizes the __shared__
204	// smem_grad[] array, so a swept value changes the static SMEM footprint and the
205	// chunk loop bounds; correctness (no overrun, matching the global-grad path)
206	// must be re-checked on the H100 parity gate, not assumed by the autotuner.
207	#ifndef SG_TUNED_GRAD_TILE
208	#define SG_TUNED_GRAD_TILE 1024
209	#endif
210	static constexpr int kGradTile = SG_TUNED_GRAD_TILE;   // floats / SMEM grad tile
211	
212	template <ModelId M, OptId Opt>
213	__device__ void fused_backward_optimizer_stage(
214	        const PersistentContext& ctx,
215	        float* __restrict__ params,
216	        const float* __restrict__ acts,
217	        const int* sizes, const int* offsets,
218	        int step, const FusedOptState& st) {
219	    __shared__ int task_slot;
220	    __shared__ float smem_grad[kGradTile];
221	    TaskQueue q = ctx.queue();
222	    for (int t = q.next_block(&task_slot); t < ctx.n_tasks;
223	         t = q.next_block(&task_slot)) {
224	        const int n = sizes[t];
225	        const int64_t off = (int64_t)offsets[t];   // #2 int64 base
226	        // Tile the tensor; each tile's grad lives in SMEM, consumed in place by
227	        // the optimizer (no global grad write/read for this tensor).
228	        for (int c0 = 0; c0 < n; c0 += kGradTile) {
229	            const int chunk = (n - c0 < kGradTile) ? (n - c0) : kGradTile;
230	            const int64_t chunk_base = off + c0;
231	            // Backward: compute grad of this chunk into SMEM (element-local).
232	            for (int i = threadIdx.x; i < chunk; i += blockDim.x) {
233	                const int64_t gi = chunk_base + i;
234	                smem_grad[i] = acts[gi] * model_activation_grad<M>(params[gi]);
235	            }
236	            __syncthreads();
237	            // Optimizer: read grad from the SMEM tile. Rebase params + state to
238	            // this chunk so apply_optimizer's chunk-local idx addresses the
239	            // correct global params/m/v while grad comes from SMEM.
240	            const FusedOptState ts = rebase_state<Opt>(st, chunk_base);
241	            float* __restrict__ p = params + chunk_base;
242	            const float* __restrict__ g = smem_grad;   // SMEM-resident grad
243	            const int n4 = chunk >> 2;
244	            for (int j = threadIdx.x; j < n4; j += blockDim.x) {
245	                const int64_t base = (int64_t)j << 2;
246	                apply_optimizer<Opt>(p, g, base + 0, step, ts);
247	                apply_optimizer<Opt>(p, g, base + 1, step, ts);
248	                apply_optimizer<Opt>(p, g, base + 2, step, ts);
249	                apply_optimizer<Opt>(p, g, base + 3, step, ts);
250	            }
251	            for (int i = (n4 << 2) + (int)threadIdx.x; i < chunk;
252	                 i += blockDim.x) {
253	                apply_optimizer<Opt>(p, g, (int64_t)i, step, ts);
254	            }
255	            __syncthreads();   // tile reuse: all opt reads done before next fill
256	        }
257	    }
258	}
259	
260	// =========================================================================
261	//  The L3/L1 persistent megakernel. ONE launch composes the real model stages
262	//  (L3 only) and the real optimizer tail, separated by the hand-built grid
263	//  barrier (§1.4) whose last arriver resets the task-queue counter race-free.
264	//  Launch config (host): gridDim.x = #SMs, blockDim.x = 256 = TWO Hopper
265	//  warp-groups (§3.4). Warp-group 0 (threads 0..127) is the producer and
266	//  deallocs its register file down to kProducerRegsF; warp-group 1 (threads
267	//  128..255) is the consumer and allocs up to kConsumerRegsF. setmaxnreg is
268	//  warp-group-uniform, so the call is issued by all 128 lanes of each group.
269	//
270	//  Behavior-preserving: setmaxnreg only repartitions the SM register file
271	//  between the two warp-groups; it does NOT change any computed value. All 256
272	//  threads still execute the same grid-stride element-local stages (whose
273	//  shared reduction / staging buffers are sized for 256), so __syncthreads is
274	//  well-formed and the results are identical to the single-warp-group launch.
275	// =========================================================================
276	template <ModelId M, OptId Opt, FuseTier Tier>
277	__global__ void __launch_bounds__(kFusedBlockThreads)
278	fused_megakernel(PersistentContext ctx,
279	                 float* __restrict__ params,
280	                 const float* __restrict__ input,
281	                 float* __restrict__ acts,
282	                 float* __restrict__ grad,
283	                 const int* __restrict__ sizes,
284	                 const int* __restrict__ offsets,
285	                 float lr, int step, FusedOptState st) {
286	    GridBarrier bar = ctx.barrier();
287	
288	    // §3.4 warp-group register repartition: producer WG (0) gives registers
289	    // back; consumer WG (1) claims the large file. Uniform within each WG.
290	    const int warp_group = threadIdx.x / kWarpGroupThreads;
291	    if (warp_group == 0) {
292	        wgs::warpgroup_reg_dealloc<kProducerRegsF>();
293	    } else {
294	        wgs::warpgroup_reg_alloc<kConsumerRegsF>();
295	    }
296	
297	    if constexpr (Tier == FuseTier::L3) {
298	        // ── Phase 1: real model forward (writes acts to global; see the Stage 5
299	        //    note above for why acts stays global across the fwd→bwd barrier). ─
300	        // #4: the task-queue reset for the NEXT phase is folded into the grid
301	        // barrier's last-arriver critical section (sync_reset). The reset lands
302	        // before the generation bump, so every CTA crossing into the fused
303	        // backward+optimizer phase sees a zeroed counter.
304	        model_forward_stage<M>(ctx, params, input, acts, sizes, offsets);
305	        bar.sync_reset(ctx.g_next_task);
306	        // ── Phase 2 (Stage 5 TRUE FUSION): backward + optimizer in ONE pass,
307	        //    grad held in a SMEM tile (no global grad round-trip), with the
308	        //    bwd→opt grid barrier eliminated (see fused_backward_optimizer_stage).
309	        st.lr = lr;
310	        fused_backward_optimizer_stage<M, Opt>(ctx, params, acts, sizes,
311	                                               offsets, step, st);
312	        // grad (param) unused on the L3 path now — the grad is SMEM-resident.
313	        (void)grad;
314	    } else {
315	        // ── L1: model fwd/bwd are the framework's own launches; this kernel is
316	        //    the fused optimizer tail only (reads grad from global). ───────────
317	        st.lr = lr;
318	        fused_optimizer_stage<Opt>(ctx, params, grad, sizes, offsets, step, st);
319	    }
320	}
321	
322	// =========================================================================
323	//  Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
324	//
325	//  HANG-FREEDOM (Stage 1 fix) — the L3 kernel rendezvouses ALL launched CTAs at
326	//  GridBarrier::sync_reset, which spins until exactly ctx.n_ctas CTAs arrive.
327	//  With an ordinary <<<>>> launch that has NO co-residency guarantee: if the
328	//  kernel's per-SM occupancy is < 1 block (register/smem pressure — the L3 cells
329	//  run ~168 regs / ~65 KB smem), some of the gridDim.x==#SMs CTAs never become
330	//  resident, never arrive, and the resident CTAs spin FOREVER. (cudaLaunch
331	//  Cooperative would error -1 in that case, but the plain launch just hangs.)
332	//
333	//  MECHANISM CHOSEN: occupancy-capped grid + co-residency assert (mechanism (a)
334	//  in the task). We query cudaOccupancyMaxActiveBlocksPerMultiprocessor for THIS
335	//  exact kernel instantiation at the launch block size and cap gridDim.x to
336	//  (occ_blocks_per_sm * #SMs) — but, because every persistent CTA must hold a
337	//  full warm optimizer-state slice and we pin ONE per SM (§1.3), we launch
338	//  exactly min(#SMs, occ * #SMs) == #SMs ONLY WHEN occ >= 1. If the kernel
339	//  cannot place even one block per SM (occ == 0) we REFUSE to launch (return
340	//  cudaErrorLaunchOutOfResources) instead of hanging. The assert documents the
341	//  invariant in debug builds; the runtime check enforces it in release builds.
342	//  We deliberately keep at most 1 CTA/SM resident (the §1.3 pin) so the barrier
343	//  set size equals the number of co-resident CTAs — never more than can fit.
344	//
345	//  This is preferred over cudaLaunchCooperativeKernel here because (a) it needs
346	//  no kernel attribute / driver cooperative-launch capability probe, (b) it
347	//  preserves the existing reusable hand-built GridBarrier (§1.4) which is the
348	//  whole point of NOT requiring a cooperative grid, and (c) it is fully compile-
349	//  checkable without silicon. The barrier counters (g_arrived / g_generation)
350	//  and the task counter (g_next_task) are device-zeroed before each launch so a
351	//  stale generation/arrival from a prior step can never desync the rendezvous.
352	// =========================================================================
353	template <ModelId M, OptId Opt, FuseTier Tier>
354	cudaError_t launch_fused_megakernel(
355	        PersistentContext ctx,
356	        float* params, const float* input, float* acts, float* grad,
357	        const int* sizes, const int* offsets,
358	        float lr, int step, FusedOptState st, cudaStream_t stream) {
359	    int dev = 0;
360	    cudaError_t err = cudaGetDevice(&dev);
361	    if (err != cudaSuccess) return err;
362	    int n_sms = 0;
363	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
364	    if (err != cudaSuccess) return err;
365	
366	    // Co-residency guarantee: how many blocks of THIS kernel actually fit on one
367	    // SM at the launch block size? If < 1, the grid barrier could never complete
368	    // (a non-resident CTA never arrives) — so we must NOT launch a gridDim that
369	    // relies on a CTA that cannot be placed.
370	    int occ_blocks_per_sm = 0;
371	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
372	        &occ_blocks_per_sm,
373	        (const void*)&fused_megakernel<M, Opt, Tier>,
374	        kFusedBlockThreads, /*dynamicSMemBytes=*/0);
375	    if (err != cudaSuccess) return err;
376	    // Hang-freedom invariant: at least one block per SM must be resident, or the
377	    // GridBarrier rendezvous of n_ctas CTAs can never be satisfied.
378	    assert(occ_blocks_per_sm >= 1 &&
379	           "fused_megakernel: 0 blocks/SM occupancy — GridBarrier would hang; "
380	           "reduce register/smem footprint or this cell must run L1 (no grid "
381	           "barrier).");
382	    if (occ_blocks_per_sm < 1) {
383	        // Release-build enforcement: refuse rather than hang.
384	        return cudaErrorLaunchOutOfResources;
385	    }
386	
387	    // §1.3: pin exactly ONE persistent CTA per SM (keeps each SM's optimizer-
388	    // state slice L2-warm). occ>=1 guarantees that single CTA per SM is co-
389	    // resident, so all n_sms CTAs rendezvous at the barrier — no hang.
390	    const unsigned launch_ctas = (unsigned)n_sms;
391	    ctx.n_ctas = launch_ctas;
392	
393	    // Device-zero the barrier + task counters before EACH launch so no stale
394	    // generation/arrival from a prior step can desync the rendezvous (the
395	    // GridBarrier reuse argument in megakernel_common.cuh assumes a zeroed start).
396	    if (ctx.g_arrived != nullptr) {
397	        err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream);
398	        if (err != cudaSuccess) return err;
399	    }
400	    if (ctx.g_generation != nullptr) {
401	        err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream);
402	        if (err != cudaSuccess) return err;
403	    }
404	    if (ctx.g_next_task != nullptr) {
405	        err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream);
406	        if (err != cudaSuccess) return err;
407	    }
408	
409	    // 256 threads = two Hopper warp-groups for the §3.4 producer/consumer
410	    // register split (kProducerRegsF / kConsumerRegsF).
411	    dim3 grid(launch_ctas), block(kFusedBlockThreads);
412	    fused_megakernel<M, Opt, Tier><<<grid, block, 0, stream>>>(
413	        ctx, params, input, acts, grad, sizes, offsets, lr, step, st);
414	    return cudaGetLastError();
415	}
416	
417	}}} // namespace sg::fused::sm90
418	
419	#endif  // SG_FUSED_SM90_FUSED_MEGAKERNEL_CUH_
