114	// FP32 vec4 fast path for the Adam apply: float4 traffic, canonical step 4×.
115	//
116	// Register-sanitize pattern (matches grokadamw/adamw/lion): load param/state
117	// with cached ld_f32v4, sam_dir + grad with read-only ldg_f32v4 (const cache),
118	// zero any non-finite gradient lane IN REGISTERS (sg_sanitize_grad4), then CALL
119	// the canonical scalar looksam_apply_step 4× on the register lanes. Math is
120	// single-sourced in algorithms/looksam.h — NOT re-typed here.
121	//
122	// BEHAVIORAL NOTE: this path no longer writes the sanitized gradient back to the
123	// caller's grad buffer on a NaN/Inf — the prior SG_SANITIZE_GRAD4_INPLACE here
124	// was a redundant global writeback (the scalar looksam_apply_step reads the
125	// already-sanitized REGISTER lane &g.x, never grad4 in memory), so it cost one
126	// extra STG.E.128 per 4 elements with no effect on the result. The vec4 path now
127	// matches the register-sanitize family: it does NOT mutate the caller's grad on
128	// NaN. The scalar (non-vec4) looksam_apply_kernel path is UNCHANGED.
129	//
130	// SASS expectation post-rebuild: the redundant per-element STG.E.128 writeback
131	// of the grad is gone; the grad load stays a const-cached LDG.E.128.
132	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_TUNED_MIN_BLOCKS)
133	looksam_apply_kernel_vec4_fp32(
134	    float4* param4, float4* exp_avg4, float4* exp_avg_sq4,
135	    const float4* sam_dir4, const float4* grad4,
136	    float alpha, float lr, float beta1, float beta2, float eps, float wd,
137	    float bc1, float bc2, int64_t N4
138	) {
139	    const int64_t stride = prim::grid_stride();
140	    for (int64_t i = prim::grid_stride_index(); i < N4; i += stride) {
141	        float4 p  = prim::ld_f32v4(param4 + i);
142	        float4 m  = prim::ld_f32v4(exp_avg4 + i);
143	        float4 v  = prim::ld_f32v4(exp_avg_sq4 + i);
144	        float4 d  = prim::ldg_f32v4(sam_dir4 + i);
145	        float4 g  = prim::ldg_f32v4(grad4 + i);
146	        ::grokking::sm90::sg_sanitize_grad4(g);
147	        #pragma unroll
148	        for (int u = 0; u < 4; ++u) {
149	            looksam_apply_step(&p.x, &m.x, &v.x, &d.x, &g.x,
150	                               alpha, lr, beta1, beta2, eps, wd, bc1, bc2, u);
151	        }
152	        prim::st_f32v4(param4 + i, p);
153	        prim::st_f32v4(exp_avg4 + i, m);
154	        prim::st_f32v4(exp_avg_sq4 + i, v);
155	    }
156	}
