158	void launch_looksam_perturb(
159	    torch::Tensor param, torch::Tensor backup,
160	    torch::Tensor grad, float scale
161	) {
162	    const int64_t N = param.numel();
163	    if (N == 0) return;
164	    auto stream = at::cuda::getCurrentCUDAStream().stream();
165	    const int block = SG_TUNED_BLOCK_SIZE;
166	    // Clamp the grid in int64 (N can exceed 2^31) then cast the grid dim to int
167	    // (grid dims are int; the element index inside the kernel is int64_t).
168	    const int grid = static_cast<int>(
169	        std::min<int64_t>(65535, (N + block - 1) / block));
170	
171	    AT_DISPATCH_FLOATING_TYPES_AND2(
172	        at::ScalarType::Half, at::ScalarType::BFloat16,
173	        param.scalar_type(), "looksam_perturb", [&] {
174	            looksam_perturb_kernel<scalar_t, scalar_t><<<grid, block, 0, stream>>>(
175	                param.data_ptr<scalar_t>(),
176	                backup.data_ptr<scalar_t>(),
177	                grad.data_ptr<scalar_t>(),
178	                scale, N);
179	            SG_LAUNCH_CHECK(stream);
180	        });
181	}
