230	void launch_looksam_apply(
231	    torch::Tensor& param,
232	    torch::Tensor& exp_avg,
233	    torch::Tensor& exp_avg_sq,
234	    const torch::Tensor& sam_dir,
235	    const torch::Tensor& grad,
236	    float alpha, float lr, float beta1, float beta2, float eps, float wd,
237	    float bc1, float bc2
238	) {
239	    const int64_t N = param.numel();
240	    if (N == 0) return;
241	    auto stream = at::cuda::getCurrentCUDAStream().stream();
242	
243	    // §6.1: keep the Adam moments (m, v) L2-resident across the SAM apply.
244	    prim::L2PersistScope l2(stream,
245	        exp_avg.data_ptr(), exp_avg.nbytes(),
246	        exp_avg_sq.data_ptr(), exp_avg_sq.nbytes());
247	
248	    const int block = SG_TUNED_BLOCK_SIZE;
249	    // Clamp the grid in int64 (N can exceed 2^31) then cast the grid dim to int
250	    // (grid dims are int; the element index inside the kernel is int64_t).
251	    const int grid = static_cast<int>(
252	        std::min<int64_t>(65535, (N + block - 1) / block));
253	
254	    const bool all_fp32 = param.scalar_type() == torch::kFloat32 &&
255	                          grad.scalar_type() == torch::kFloat32;
256	
257	    if (SG_TUNED_VEC_WIDTH == 4 && all_fp32 &&
258	        prim::is_vec4_alignable(param.data_ptr(), N) &&
259	        prim::is_vec4_alignable(exp_avg.data_ptr(), N) &&
260	        prim::is_vec4_alignable(exp_avg_sq.data_ptr(), N) &&
261	        prim::is_vec4_alignable(sam_dir.data_ptr(), N) &&
262	        prim::is_vec4_alignable(grad.data_ptr(), N)) {
263	        const int64_t N4 = N / 4;
264	        const int grid4 = static_cast<int>(
265	            std::min<int64_t>(65535, (N4 + block - 1) / block));
266	        looksam_apply_kernel_vec4_fp32<<<grid4, block, 0, stream>>>(
267	            reinterpret_cast<float4*>(param.data_ptr<float>()),
268	            reinterpret_cast<float4*>(exp_avg.data_ptr<float>()),
269	            reinterpret_cast<float4*>(exp_avg_sq.data_ptr<float>()),
270	            reinterpret_cast<const float4*>(sam_dir.data_ptr<float>()),
271	            reinterpret_cast<const float4*>(grad.data_ptr<float>()),
272	            alpha, lr, beta1, beta2, eps, wd, bc1, bc2, N4);
273	        SG_LAUNCH_CHECK(stream);
274	        return;
275	    }
276	
277	    AT_DISPATCH_FLOATING_TYPES_AND2(
278	        at::ScalarType::Half, at::ScalarType::BFloat16,
279	        param.scalar_type(), "looksam_apply", [&] {
280	            looksam_apply_kernel<scalar_t, scalar_t, SG_TUNED_UNROLL>
281	                <<<grid, block, 0, stream>>>(
282	                param.data_ptr<scalar_t>(),
283	                exp_avg.data_ptr<float>(),
284	                exp_avg_sq.data_ptr<float>(),
285	                sam_dir.data_ptr<float>(),
286	                grad.data_ptr<scalar_t>(),
287	                alpha, lr, beta1, beta2, eps, wd, bc1, bc2, N);
288	            SG_LAUNCH_CHECK(stream);
289	        });
290	}
