293	// Fused direction-adjust: grad = (1 - lambda) * grad + lambda * grad_norm * (v_dir * inv_norm)
294	__global__ void looksam_direction_adjust_kernel(
295	    float* grad, const float* v_dir,
296	    float inv_norm, float lambda, float grad_norm, int64_t N
297	) {
298	    const int64_t stride = prim::grid_stride();
299	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
300	        float g = grad[i];
301	        float d = v_dir[i] * inv_norm;
302	        grad[i] = (1.0f - lambda) * g + lambda * grad_norm * d;
303	    }
304	}
