311	    if (N == 0) return;
312	    auto stream = at::cuda::getCurrentCUDAStream().stream();
313	    const int block = SG_TUNED_BLOCK_SIZE;
314	    // Clamp the grid in int64 (N can exceed 2^31) then cast the grid dim to int
315	    // (grid dims are int; the element index inside the kernel is int64_t).
316	    const int grid = static_cast<int>(
317	        std::min<int64_t>(65535, (N + block - 1) / block));
318	    looksam_direction_adjust_kernel<<<grid, block, 0, stream>>>(
319	        grad.data_ptr<float>(), v_dir.data_ptr<float>(),
320	        inv_norm, lambda, grad_norm, N);
321	    SG_LAUNCH_CHECK(stream);
322	}
