324	// Reduce: results[0] = ||sam_grad - grad||, results[1] = ||grad||.
325	void launch_looksam_norm_reduce(
326	    torch::Tensor grad, torch::Tensor sam_grad,
327	    torch::Tensor results
328	) {
329	    auto diff = (sam_grad - grad).to(torch::kFloat32);
330	    auto dn = diff.norm();
331	    auto gn = grad.to(torch::kFloat32).norm();
332	    results[0] = dn;
333	    results[1] = gn;
334	}
