111	// Rebase a FusedOptState's per-element state pointers to a parameter-tensor
112	// slice at `off` within the flat [m|v|extra] layout. Per-TENSOR fields (the
113	// NeuralGrok psi MLP weights) and all scalars pass through unchanged.
114	template <OptId Opt>
115	__device__ __forceinline__ FusedOptState
116	rebase_state(const FusedOptState& s, int64_t off) {
117	    FusedOptState t = s;  // scalars + per-tensor pointers copy as-is
118	    if (t.exp_avg)    t.exp_avg    += off;
119	    if (t.exp_avg_sq) t.exp_avg_sq += off;
120	    if (t.ema)        t.ema        += off;
121	    if (t.sam_dir)    t.sam_dir    += off;
122	    if (t.s_track)    t.s_track    += off;
123	    if (t.mu)         t.mu         += off;
124	    if (t.orth)       t.orth       += off;
125	    if (t.smart_grad) t.smart_grad += off;
126	    if (t.param_init) t.param_init += off;   // Prodigy trajectory anchor p0
127	    return t;
128	}
