130	// The L3-REAL decoder megakernel needs the token path + a grad-partial workspace
131	// in addition to the FuseTier::{L1,L3} ABI. We keep it a SEPARATE kernel +
132	// launcher (not folded into fused_megakernel) so the surrogate path is untouched.
133	//
134	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
135	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
136	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
137	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
138	// total == kDecTotalElems == 422755.
139	
140	struct DecoderTokenCtx {
141	    const int* tokens;   // [B, kSeq] int32 token ids in [0, kVocab)
142	    const int* targets;  // [B]       int32 target ids
143	    int        B;        // batch size (full-batch in the race ≈ 4191)
144	    float*     workspace; // grad partials + loss partials + reduced loss
145	    float*     loss_out;  // device float the kernel writes the mean loss into
146	};
147	
148	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
149	//    threads/CTA. The smem holds ONE DecSampleSmem (≈42 KB, < 48 KB static cap —
150	//    no dynamic-smem opt-in, so the occupancy≥1 guard with dynamicSMemBytes=0 in
151	//    the launcher is unchanged). ────────────────────────────────────────────────
152	// sizes/offsets are NOT host-passed: the per-tensor numel/offset live in the
153	// generated __constant__ tables kDecSizes/kDecOffsets (decoder_layout.cuh), so
154	// the reduce + optimizer phases read them directly. This also lets the host side
155	// (dispatch.cpp) avoid building any layout tensors.
156	template <OptId Opt>
157	__global__ void __launch_bounds__(SG_TUNED_MEGA_BLOCK)
158	fused_decoder_megakernel(PersistentContext ctx,
159	                         float* __restrict__ params,
160	                         DecoderTokenCtx tok,
161	                         float* __restrict__ grad,        // reduced grad [total]
162	                         float lr, int step, FusedOptState st) {
163	    __shared__ DecSampleSmem sm;
164	    GridBarrier bar = ctx.barrier();
165	    const int cta = blockIdx.x;
166	    const int nCTA = (int)ctx.n_ctas;
167	    const int64_t total = kDecTotalElems;
168	    float* my_partial = tok.workspace + (int64_t)cta * total;   // this CTA's dW
169	    float* loss_part = tok.workspace + (int64_t)nCTA * total;   // [nCTA]
170	
171	    // §3.4 register repartition (producer WG gives back, consumer WG claims).
172	    const int wg = threadIdx.x / 128;
173	    // warp-specialize prims live in sg::sm90::wgs (this file is sg::fused::sm90)
174	    if (wg == 0) ::sg::sm90::wgs::warpgroup_reg_dealloc<32>();
175	    else         ::sg::sm90::wgs::warpgroup_reg_alloc<200>();
176	
177	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
178	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
179	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
180	    bar.sync();   // B0
181	
182	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
183	    DecWeights w = dec_bind(params);
184	    DecGrad g = dec_bind_grad(my_partial);
185	    // Even split with remainder to the low CTAs (contiguous, deterministic).
186	    const int B = tok.B;
187	    const int base = B / nCTA, rem = B % nCTA;
188	    const int b0 = cta * base + (cta < rem ? cta : rem);
189	    const int cnt = base + (cta < rem ? 1 : 0);
190	    const int b1 = b0 + cnt;
191	    __shared__ int tok_s[dec::kSeq];   // this sample's token ids (broadcast)
192	    __shared__ int tgt_s;
193	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
194	    for (int b = b0; b < b1; ++b) {
195	        if (threadIdx.x < dec::kSeq) tok_s[threadIdx.x] = tok.tokens[(int64_t)b * dec::kSeq + threadIdx.x];
196	        if (threadIdx.x == 0) tgt_s = tok.targets[b];
197	        __syncthreads();
198	        float nll = dec_forward_sample(w, tok_s, tgt_s, &sm);
199	        dec_backward_sample(w, g, tok_s, tgt_s, B, &sm);
200	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
201	        __syncthreads();   // sample boundary: all grad writes done before reuse
202	    }
203	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
204	    bar.sync();   // B1: all CTA partials + loss slots complete
205	
206	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
207	    //    (one task = one parameter tensor; sum its elements across CTAs in
208	    //    ascending CTA index). The summation ORDER (ascending cta) is fixed, so
209	    //    the result is deterministic regardless of which CTA grabs the task. ────
210	    {
211	        __shared__ int task_slot;
212	        TaskQueue q = ctx.queue();
213	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
214	             t = q.next_block(&task_slot)) {
215	            const int n = kDecSizes[t];
216	            const int64_t off = (int64_t)kDecOffsets[t];
217	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
218	                float acc = 0.0f;
219	                // ascending CTA index → fixed fp32 summation order (deterministic).
220	                for (int c = 0; c < nCTA; ++c)
221	                    acc += tok.workspace[(int64_t)c * total + off + i];
222	                grad[off + i] = acc;
223	            }
224	        }
225	    }
226	    // Loss reduction (fp64 ordered) by CTA 0 only — the 1e-5 loss rel-tol is the
227	    // tightest gate; fp32 atomic-summing ~4191 terms can miss it.
228	    if (cta == 0 && threadIdx.x == 0) {
229	        double s = 0.0;
230	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
231	        float mean = (float)(s / (double)B);
232	        *tok.loss_out = mean;
233	    }
234	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
235	
236	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
237	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
238	    st.lr = lr;
239	    {
240	        __shared__ int task_slot;
241	        TaskQueue q = ctx.queue();
242	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
243	             t = q.next_block(&task_slot)) {
244	            const int n = kDecSizes[t];
245	            const int64_t off = (int64_t)kDecOffsets[t];
246	            const FusedOptState ts = rebase_state<Opt>(st, off);
247	            float* __restrict__ p = params + off;
248	            const float* __restrict__ gg = grad + off;
249	            for (int i = threadIdx.x; i < n; i += blockDim.x)
250	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
251	        }
252	    }
253	}
