255	// ── Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
256	//    Mirrors launch_fused_megakernel's hang-freedom contract: occupancy≥1 or
257	//    refuse (the GridBarrier rendezvous of n_ctas CTAs can never complete if a
258	//    CTA can't be placed). Zeroes the barrier+task counters per launch. ─────────
259	template <OptId Opt>
260	cudaError_t launch_fused_decoder_megakernel(
261	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
262	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream) {
263	    int dev = 0;
264	    cudaError_t err = cudaGetDevice(&dev);
265	    if (err != cudaSuccess) return err;
266	    int n_sms = 0;
267	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
268	    if (err != cudaSuccess) return err;
269	
270	    int occ = 0;
271	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
272	        &occ, (const void*)&fused_decoder_megakernel<Opt>, SG_TUNED_MEGA_BLOCK,
273	        /*dynamicSMemBytes=*/0);
274	    if (err != cudaSuccess) return err;
275	    // Hang-freedom: at least one CTA per SM must be resident or the grid barrier
276	    // can never be satisfied. The L3-REAL kernel uses ≈42 KB static smem + a high
277	    // register count; if it cannot place one block/SM, REFUSE rather than hang.
278	    assert(occ >= 1 &&
279	           "fused_decoder_megakernel: 0 blocks/SM — GridBarrier would hang. The "
280	           "decoder smem (~42KB) + regs exceed one-block-per-SM occupancy; "
281	           "reduce footprint or fall back to the L1 per-op path.");
282	    if (occ < 1) return cudaErrorLaunchOutOfResources;
283	
284	    const unsigned launch_ctas = (unsigned)n_sms;
285	    ctx.n_ctas = launch_ctas;
286	
287	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
288	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
289	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
290	
291	    dim3 grid(launch_ctas), block(SG_TUNED_MEGA_BLOCK);
292	    fused_decoder_megakernel<Opt><<<grid, block, 0, stream>>>(
293	        ctx, params, tok, grad, lr, step, st);
294	    return cudaGetLastError();
295	}
