722	// ncta_cap (default 0): if >0, launch min(n_sms, ncta_cap) CTAs instead of one
723	// per SM. The grid barrier rendezvous is over the LAUNCHED count (ctx.n_ctas),
724	// so any cap is hang-safe as long as the workspace + dW-tile/embedding ownership
725	// use the SAME nCTA (they read ctx.n_ctas). The shipped path passes 0 (full
726	// saturation); a memory-constrained TEST passes a small cap so the per-CTA
727	// scratch fits (the scratch is nCTA×slab). Determinism is preserved per fixed
728	// nCTA (the dW/embedding owner maps are functions of nCTA).
729	template <OptId Opt>
730	cudaError_t launch_fused_decoder_megakernel_tc(
731	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
732	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
733	        int ncta_cap = 0) {
734	    int dev = 0;
735	    cudaError_t err = cudaGetDevice(&dev);
736	    if (err != cudaSuccess) return err;
737	    int n_sms = 0;
738	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
739	    if (err != cudaSuccess) return err;
740	
741	    // Hang-freedom: certify one block/SM occupancy with the ACTUAL dynamic smem
742	    // (0 here — DecTcSmem is static). If the static smem + 200-reg consumer
743	    // can't place one block/SM, REFUSE (the grid barrier would hang).
744	    int occ = 0;
745	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
746	        &occ, (const void*)&fused_decoder_megakernel_tc<Opt>, SG_TC_MEGA_BLOCK,
747	        /*dynamicSMemBytes=*/0);
748	    if (err != cudaSuccess) return err;
749	    if (occ < 1) return cudaErrorLaunchOutOfResources;
750	
751	    unsigned launch_ctas = (unsigned)n_sms;
752	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
753	    ctx.n_ctas = launch_ctas;
754	    // B%16 required (the dW K-loop contracts K=T=B*kSeq and K=B in 16-step atoms,
755	    // AND it guarantees full token tiles for the projections). NO G-divisibility
756	    // guard: the split-K dW uses a FLOOR-BALANCED K-partition (dectc_dw_run_tile_
757	    // splitk) that sums to KS exactly for any KS≥G, so it works at the production
758	    // truncated B (e.g. 4176, where head KS=B/16=261 is NOT divisible by G=4).
759	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
760	
761	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
762	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
763	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
764	
765	    dim3 grid(launch_ctas), block(SG_TC_MEGA_BLOCK);
766	    fused_decoder_megakernel_tc<Opt><<<grid, block, 0, stream>>>(
767	        ctx, params, tok, grad, lr, step, st);
768	    return cudaGetLastError();
769	}
