910	__device__ void dectc_backward_tile(
911	        const DecWeights& w, int g0, int nrows, int B, const DecActs& acts,
912	        const DecTileScratch& sc, const int* __restrict__ tgt_ids,
913	        float* __restrict__ lnvec, float* __restrict__ work2,
914	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red) {
915	    const int nsamp = nrows / dec::kSeq;
916	    // LN-vec partial slots (dense order; see kLnVecTensorIdx).
917	    float* gn_n1w[dec::kLayers]; float* gn_n1b[dec::kLayers];
918	    float* gn_n2w[dec::kLayers]; float* gn_n2b[dec::kLayers];
919	    for (int li = 0; li < dec::kLayers; ++li) {
920	        gn_n1w[li] = lnvec + (int64_t)(li * 4 + 0) * dec::kD;
921	        gn_n1b[li] = lnvec + (int64_t)(li * 4 + 1) * dec::kD;
922	        gn_n2w[li] = lnvec + (int64_t)(li * 4 + 2) * dec::kD;
923	        gn_n2b[li] = lnvec + (int64_t)(li * 4 + 3) * dec::kD;
924	    }
925	    float* gn_normw = lnvec + (int64_t)8 * dec::kD;
926	    float* gn_normb = lnvec + (int64_t)9 * dec::kD;
